mapper.select:
select

from content_slot

    deleted = 0
    and code in ('home_top_swiper', 'home_article_feed')

        and (code like concat('%', #{query.keyword,jdbcType=VARCHAR}, '%')
        or name like concat('%', #{query.keyword,jdbcType=VARCHAR}, '%'))


        and page_code = #{query.pageCode,jdbcType=VARCHAR}


        and render_type = #{query.renderType,jdbcType=VARCHAR}


        and status = #{query.status,jdbcType=TINYINT}


order by page_code asc, code asc
